# -*- coding: utf-8 -*-
from gcommon import *
PA = 'parent'
ALLL = ['a3', 'a4', 'a5', 'a6', 'g1', 'g2', 'g3', 'g4']

def SEC(slug, title, desc, topic, levels, goals, intro, what, steps, ex, teacher, tips, summ, sort, icon=None):
    g = G(slug, PA, 'section', title, desc, levels, topic, goals, intro,
          [H('ماذا تجد في هذا القسم؟'), TABLE(['العنصر', 'فائدته'], what), H('كيف تستفيد منه؟'), STEPS(steps), EX(ex), H('للمعلمين'), P(teacher), TIPS(tips)], summ, sort)
    if icon: g['icon'] = icon
    return g

